import{_ as o,l as i,o as e,c as l,v as t,p as n,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"系统性对随机缺陷","description":"","frontmatter":{"title":"系统性对随机缺陷","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/systematic-vs-random-defects.md","filePath":"litho/systematic-vs-random-defects.md","lastUpdated":1789023840000}'),E={name:"litho/systematic-vs-random-defects.md"};function c(m,a,A,_,B,P){const s=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="系统性对随机缺陷" tabindex="-1">系统性对随机缺陷 <a class="header-anchor" href="#系统性对随机缺陷" aria-label="Permalink to &quot;系统性对随机缺陷&quot;">​</a></h1><div class="epigraph"><p>系统缺陷在每颗管芯同一拓扑重复，改 OPC 或规则能一次杀掉；随机缺陷按位置抽签，洁净与光子统计才是杠杆。</p><footer>—— 对照良率工程对 systematic vs random 的划分；计算光刻热点与颗粒缺陷的分工</footer></div><p><a href="/litho/critical-area">上一课</a>把随机颗粒写成 \\(A_\\mathrm{cr}\\)。缺口是分类：探针图上的重复失败是系统，散点是随机，混在一张 \\(D\\) 里会开错药。<a href="/litho/hotspot-pv">热点 PV</a> 已定义过程变化下的系统杀手；本课钉良率账的拆分。EUV 光子与化学随机，留给[下一课](/litho/stochastic-yield）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>系统：错色、OPC 不足、切线偏置、焦距地图、掩模缺陷打印。特征是空间重复或与布局相关。随机：颗粒、残留、部分光子缺孔。诊断：把失败管芯叠到设计上，看是否对齐同一 clips；与过程角相关则更像窗口问题。</p><p>缺口是<strong>两本账</strong>，不是再跑 LRC。系统用设计/OPC/PWQ 消灭，随机用洁净、过滤、剂量（对光子）和关键面积。APC 补均值 CD 可能改善系统窗口，对颗粒几乎无用。</p><h3 id="掩模缺陷是系统的一种" tabindex="-1">掩模缺陷是系统的一种 <a class="header-anchor" href="#掩模缺陷是系统的一种" aria-label="Permalink to &quot;掩模缺陷是系统的一种&quot;">​</a></h3><p>掩模上的固定缺陷在每场同一位置打印，像系统。AIMS 与掩模检测课已有；良率上应按「每场重复」识别，不要当晶圆颗粒去改轨道。</p><p><span class="marginnote">边缘环失败看起来「随机」，其实是边缘场系统。叠图要对晶圆坐标，也要对场坐标。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>叠图：管芯失败 × 设计 clips × 场坐标 × 晶圆半径。Pareto：系统 clips 清单 vs 随机密度。动作：系统走 LFD/OPC/食谱；随机走洁净与检测。与分派：系统批可能整批同源（错版），重工有效；随机按 \\(D\\) 抽检。</p><p>场坐标叠图能抓住掩模打印缺陷和扫描机指纹；设计叠图抓住 OPC 热点。两张图都要做。良率工程对 systematic vs random 的划分，操作上就是这两张叠图。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>系统失效概率对管芯近似 0 或 1（在窗口外则全死）。随机是 \\(1-e^{-DA}\\)。混合良率 \\(\\approx Y_\\mathrm{sys} \\times Y_\\mathrm{rand}\\)。把系统残差塞进 \\(D\\)，会高估洁净收益。过程变化把「临界系统」变成批间闪烁，看起来像随机，要用 PWQ 与过程角去验。</p>',14)),(e(),n(h,null,{default:r(()=>[p(s,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIL%5B%22%E6%8E%A2%E9%92%88%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20STACK%5B%22%E5%8F%A0%E8%AE%BE%E8%AE%A1%20%2F%20%E5%9C%BA%20%2F%20%E5%8D%8A%E5%BE%84%22%5D%0A%20%20STACK%20--%3E%20SYS%5B%22%E9%87%8D%E5%A4%8D%E6%8B%93%E6%89%91%20%E2%86%92%20%E7%B3%BB%E7%BB%9F%E8%B4%A6%22%5D%0A%20%20STACK%20--%3E%20RND%5B%22%E7%A9%BA%E9%97%B4%E6%95%A3%E7%82%B9%20%E2%86%92%20%E9%9A%8F%E6%9C%BA%E8%B4%A6%22%5D%0A%20%20SYS%20--%3E%20OPC%5B%22OPC%20%2F%20%E8%A7%84%E5%88%99%20%2F%20%E9%A3%9F%E8%B0%B1%22%5D%0A%20%20RND%20--%3E%20CA%5B%22%E5%85%B3%E9%94%AE%E9%9D%A2%E7%A7%AF%20%C3%97%20%E6%B4%81%E5%87%80%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>设计叠图抓 OPC，场坐标叠图抓掩模与扫描机指纹。两张图分开，药才不会开错房间。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>分类有灰色：随机热点（NILS 低处更容易颗粒桥）。仍应先修 NILS。不把本课写成检测设备手册（后课）。</p><p>后课默认：良率 Pareto 分系统与随机。下一课专门把光子/化学随机从颗粒随机里再拆一刀。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>系统对齐设计与场；随机按位置抽签。</li><li>两本账，两种杠杆；禁止用 \\(D\\) 吞热点。</li><li>掩模打印缺陷按场重复识别。</li><li>出处：良率工程 systematic/random 划分；计算光刻热点传统。</li></ul>',6))])}const C=o(E,[["render",c]]);export{u as __pageData,C as default};
